try {
  if (!db.prepare('SELECT 1 FROM tmkt_plano WHERE id=? AND empresa_id=?').get(PID, EMP)) {
    console.log('↷ migration 279: plano Black não existe ainda (277/278 criam) — ok, nada a fazer');
  } else {
    const cols = Object.keys(P);
    db.prepare('UPDATE tmkt_plano SET ' + cols.map(c=>c+'=?').join(', ') + ' WHERE id=? AND empresa_id=?')
      .run(...cols.map(c=>P[c]), PID, EMP);
    db.prepare("DELETE FROM tmkt_plano_fotos WHERE plano_id=? AND secao='galeria'").run(PID);
    const ins = db.prepare("INSERT OR IGNORE INTO tmkt_plano_fotos (id,empresa_id,plano_id,foto,legenda,ordem,secao,criado_em) VALUES (?,?,?,?,?,?,?,datetime('now'))");
    for (const f of FOTOS) ins.run(f.id, EMP, PID, f.foto, f.legenda, f.ordem, f.secao);
    console.log('✅ migration 279: plano Black real aplicado (' + FOTOS.length + ' fotos de galeria)');
  }
} catch (e) { if (!/no such table/i.test(e.message)) throw e; console.log('↷ migration 279: tabelas ainda não existem — ok'); }
